```python
import requests
from datetime import datetime
import time

def get_twitter_account_urls():
    urls = []
    for i in range(1, 3):
        urls.append(
            f"https://twitter.com/search?q=%s&include_ entities=true&src=organic&l=en&vertical=default&time_range=today" % "SE"
        )
    return urls

def fetch_tweet_data(url):
    headers = {
        "User-Agent": "Fetcher/1.0 (python-twitter/python-twitter)"
    }
    response = requests.get(url, headers=headers, timeout=5)
    return response.json()

def parse_tweet(tweet_data):
    """Extract text, time, user ID"""
    text = tweet_data.get("text") or tweet_data.get("full_text")
    user_id = tweet_data.get("user")
    if not user_id:
        user_id = tweet_data.get("from_user")
    return {"text": text, "user": user_id}

def post_to_twitter(tweet_data, url):
    try:
        r = requests.post(url, json=tweet_data, timeout=120)
        return r.status_code == 201
    except Exception as e:
        print(f"Error posting: {e}")

